import { spawn } from "node:child_process";
import path from "node:path";
import { NextResponse } from "next/server";

export const runtime = "nodejs";

const MAX_DAYS = 90;
const MAX_RESPONSE_BYTES = 48 * 1024;
const DATA_FETCH_TIMEOUT_MS = 60_000;
const NO_STORE_HEADERS = { "Cache-Control": "no-store, max-age=0" };

/** Resolve the repository root from the local Next app directory. */
function getProjectRoot(): string {
  return process.env.GARMIN_PROJECT_ROOT ?? path.resolve(process.cwd(), "..");
}

/** Resolve the project virtualenv interpreter, with a PATH fallback for other setups. */
function getPython(projectRoot: string): string {
  return process.env.GARMIN_PYTHON_EXECUTABLE ?? path.join(
    projectRoot,
    ".venv",
    process.platform === "win32" ? "Scripts" : "bin",
    process.platform === "win32" ? "python.exe" : "python",
  );
}

/** Fetch structured daily metrics through the existing local Python client. */
function runDashboardFetch(projectRoot: string, days: number): Promise<string> {
  const scriptPath = path.join(projectRoot, "health_dashboard.py");
  return new Promise((resolve, reject) => {
    let output = "";
    let settled = false;
    let timeout: NodeJS.Timeout;
    const child = spawn(/*turbopackIgnore: true*/ getPython(projectRoot), [scriptPath, "--days", String(days)], {
      cwd: projectRoot,
      env: process.env,
      windowsHide: true,
    });

    const finish = (error?: Error) => {
      if (settled) {
        return;
      }
      settled = true;
      clearTimeout(timeout);
      if (error) {
        reject(error);
      } else {
        resolve(output.trim());
      }
    };

    timeout = setTimeout(() => {
      child.kill();
      finish(new Error("data-fetch-timeout"));
    }, DATA_FETCH_TIMEOUT_MS);

    child.stdout.on("data", (chunk: Buffer) => {
      output += chunk.toString("utf8");
      if (Buffer.byteLength(output, "utf8") > MAX_RESPONSE_BYTES) {
        child.kill();
        finish(new Error("data-output-too-large"));
      }
    });
    child.on("error", () => finish(new Error("data-fetch-start-failed")));
    child.on("close", (code) => {
      if (code === 0) {
        finish();
      } else {
        finish(new Error("data-fetch-failed"));
      }
    });
  });
}

/** Return private, uncached Garmin health metrics for the selected date range. */
export async function POST(request: Request): Promise<NextResponse> {
  const origin = request.headers.get("origin");
  const expectedHost = request.headers.get("x-forwarded-host") ?? request.headers.get("host");
  const expectedProtocol = request.headers.get("x-forwarded-proto") ?? new URL(request.url).protocol.slice(0, -1);
  let originUrl: URL | null = null;
  try {
    originUrl = origin ? new URL(origin) : null;
  } catch {
    originUrl = null;
  }
  if (!originUrl || originUrl.host !== expectedHost || originUrl.protocol !== `${expectedProtocol}:`) {
    return NextResponse.json({ error: "Request must come from this app." }, { status: 403, headers: NO_STORE_HEADERS });
  }

  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: "Send a valid JSON request." }, { status: 400, headers: NO_STORE_HEADERS });
  }

  const days = typeof body === "object" && body !== null && "days" in body ? body.days : 30;
  if (typeof days !== "number" || !Number.isInteger(days) || days < 1 || days > MAX_DAYS) {
    return NextResponse.json(
      { error: `Choose a date range from 1 to ${MAX_DAYS} days.` },
      { status: 400, headers: NO_STORE_HEADERS },
    );
  }

  const projectRoot = getProjectRoot();
  try {
    const output = await runDashboardFetch(projectRoot, days);
    const payload: unknown = JSON.parse(output);
    if (typeof payload !== "object" || payload === null || !("metrics" in payload) || !("period" in payload)) {
      throw new Error("invalid-dashboard-payload");
    }
    return NextResponse.json(payload, { headers: NO_STORE_HEADERS });
  } catch {
    return NextResponse.json(
      { error: "Garmin data could not be loaded. Check your local Personal API key and connection." },
      { status: 502, headers: NO_STORE_HEADERS },
    );
  }
}